"function getRandomCharacter(characters) {
    return characters.charAt(Math.floor(Math.random() * characters.length));
}

function shuffle(value) {
    let characters = value.split('');
    for (let index = characters.length - 1; index > 0; index--) {
        const randomIndex = Math.floor(Math.random() * (index + 1));
        const temporaryCharacter = characters[index];
        characters[index] = characters[randomIndex];
        characters[randomIndex] = temporaryCharacter;
    }
    return characters.join('');
}

function generatePassword() {
    const upperCharacters = 'ABCDEFGHJKMNPQRSTUVWXYZ';
    const lowerCharacters = 'abcdefghjkmnpqrstuvwxyz';
    const numericCharacters = '23456789';
    const specialCharacters = '!#$@*?';
    const allCharacters = upperCharacters + lowerCharacters + numericCharacters + specialCharacters;
    let password = getRandomCharacter(upperCharacters);
    password += getRandomCharacter(lowerCharacters);
    password += getRandomCharacter(numericCharacters);
    password += getRandomCharacter(specialCharacters);
    while (password.length < 12) {
        password += getRandomCharacter(allCharacters);
    }
    return shuffle(password);
}

generatePassword();"
